function App() {
  const [open, setOpen] = useState(false);
  const opener = useRef(null); const closeButton = useRef(null);
  useEffect(() => { if (open) closeButton.current?.focus(); }, [open]);
  const close = () => { setOpen(false); requestAnimationFrame(() => opener.current?.focus()); };
  return <div><button ref={opener} onClick={() => setOpen(true)}>Open details</button>{open && <div role="dialog" aria-modal="true" aria-labelledby="dialog-title" style={{padding:20,border:"1px solid #60a5fa",marginTop:12}}><h2 id="dialog-title">Details</h2><p>Keyboard focus starts here and returns to the opener.</p><button ref={closeButton} onClick={close}>Close</button></div>}</div>;
}
